import {money,PRICING} from './pricing.js';
import {AIRLINES,AIRLINE_CHECKED} from './airlines.js';
export const arrow='<span aria-hidden="true">↗</span>';
const ext=(url,label)=>`<a href="${url}" target="_blank" rel="noopener noreferrer">${label} ${arrow}</a>`;
export function pageIntro(label,title,description=''){return `<section class="page-intro"><div class="shell"><p class="eyebrow">${label}</p><h1>${title}</h1>${description?`<p class="lead">${description}</p>`:''}</div></section>`;}
function gallery(){return `<div class="product-gallery"><figure class="gallery-stage"><img id="gallery-image" src="assets/easyfit-black.jpg" alt="Black Bike Box Alan Triathlon Aero Easyfit" width="800" height="600" fetchpriority="high"></figure><div class="gallery-controls" role="group" aria-label="Case photographs"><button type="button" data-image="easyfit-black" aria-pressed="true" aria-label="Show outside"><img src="assets/easyfit-black.jpg" alt="Outside" width="80" height="60"></button><button type="button" data-image="easyfit-open" aria-pressed="false" aria-label="Show inside"><img src="assets/easyfit-open.jpg" alt="Inside" width="80" height="60"></button><span>Triathlon Aero Easyfit · Black</span></div></div>`;}
function specs(){return `<dl class="spec-list"><div><dt>Empty weight</dt><dd>Approx. 13.5 kg</dd></div><div><dt>Dimensions</dt><dd>133 × 94 × 50 cm</dd></div><div><dt>Colour</dt><dd>Black</dd></div></dl>`;}
function quickForm(today,max){return `<form id="quick-dates" class="home-hire-form"><div class="quick-title"><h2>Plan your hire</h2><span>£11 / day · 5-day minimum</span></div><div class="field-grid"><label>Collect in Bath<input type="date" name="start" min="${today}" max="${new Date(Date.parse(max)-4*86400000).toISOString().slice(0,10)}" required aria-label="Collection date"></label><label>Return to Bath<input type="date" name="end" min="${today}" max="${max}" required aria-label="Return date"></label></div><p class="form-error" id="quick-error" role="alert"></p><div id="quick-quote" aria-live="polite"></div><button class="button" type="submit">Continue with your dates <span aria-hidden="true">→</span></button><p class="quick-footnote">£150 refundable deposit. Collection and return by appointment.</p></form>`;}
export function faq(){return `<div class="faq"><details><summary>Will my bike fit?<span aria-hidden="true">+</span></summary><p>Send your bike model, frame size and cockpit details with your enquiry. Check the manufacturer’s fit guide for your setup.</p></details><details><summary>Do the handlebars need removing?<span aria-hidden="true">+</span></summary><p>The Easyfit accommodates many bikes with less dismantling. Your airline may still require handlebars aligned with the frame and pedals removed.</p></details><details><summary>What does it cost?<span aria-hidden="true">+</span></summary><p>£11 per calendar day, minimum 5 days. A £150 refundable deposit is added. Late returns are charged at £40 per day.</p></details></div>`;}
export function homePage(today,max){return `<section class="landing-hero"><div class="shell hero-layout"><div class="hero-intro"><p class="eyebrow"><span class="location-dot" aria-hidden="true"></span>Bike box hire / Bath, Somerset</p><h1>Your bike.<br><em>New roads.</em></h1><p>Take your own bike on the trip. Hire a black Bike Box Alan Easyfit, with collection and return in Bath.</p></div><div class="hero-product">${gallery()}<div class="hero-specs"><span><strong>13.5 kg</strong>Approx. empty weight</span><span><strong>133 × 94 × 50 cm</strong>External dimensions</span><a href="#/box">Explore the box ${arrow}</a></div></div><div class="hero-quote">${quickForm(today,max)}</div></div><span class="hero-track" aria-hidden="true"></span></section>
<section class="hire-explainer"><div class="shell"><div class="explainer-heading"><p class="eyebrow">From Bath to the start line</p><h2>Three steps. One bike box.</h2></div><ol><li><span>01</span><div><h3>Choose your dates</h3><p>£11 a day, with your full quote shown upfront.</p></div></li><li><span>02</span><div><h3>Collect in Bath</h3><p>Bring photo ID. We’ll check the case together.</p></div></li><li><span>03</span><div><h3>Ride. Return.</h3><p>Return the case for inspection and deposit settlement.</p></div></li></ol></div></section>
<section class="section"><div class="shell flight-summary"><div><p class="eyebrow">Before you fly</p><h2>Know your allowance.</h2><p>The case weighs around 13.5 kg empty. Check your packed weight and your airline’s bike rules.</p><a class="text-link" href="#/airlines">Airline guide & weight calculator ${arrow}</a></div><dl><div><dt>easyJet</dt><dd>32 kg</dd></div><div><dt>Ryanair</dt><dd>30 kg</dd></div><div><dt>Jet2</dt><dd>32 kg</dd></div><div><dt>BA / TUI</dt><dd>Check your fare</dd></div></dl></div></section>
<section class="local-section"><div class="shell local-grid"><div class="local-photo"><img src="assets/bath.jpg" alt="Pulteney Bridge in Bath" width="1600" height="1000" loading="lazy"></div><div class="local-copy"><p class="eyebrow">Your local handover</p><h2>Collect in Bath.<br>Then take off.</h2><p>Collection and return by appointment. A question about the box or your bike? Get in touch.</p><a class="contact-email" href="mailto:hello@bikeboxbath.co.uk">hello@bikeboxbath.co.uk ${arrow}</a><a class="quiet-link" href="#/pricing">How hire works ${arrow}</a></div></div></section>
<section class="section"><div class="shell faq-layout"><h2>Before your first hire.</h2>${faq()}</div></section>`;}
export function boxPage(){return `${pageIntro('The box','Triathlon Aero Easyfit.')}<section class="section section-top-small"><div class="shell product-layout">${gallery()}<div class="product-info"><p class="eyebrow">Bike Box Alan · Black</p><h2>The details.</h2><p>A hard-shell case designed for many road, aero and triathlon bikes. Fit depends on your frame, saddle height and cockpit.</p>${specs()}<p class="small">External dimensions: length × height × width.</p><a class="button" href="#/enquire">Plan your hire ${arrow}</a></div></div></section><section class="section product-notes"><div class="shell"><div><h2>Before packing.</h2><p>Follow the manufacturer’s instructions for your bike. Check wheel and pedal removal, protect contact points and secure loose parts.</p>${ext('https://bikeboxalan.com/product/triathlon-easyfit/','Product & packing guide')}</div><div><h2>Fit & transport.</h2><p>Check the bike measurements, your airline’s case restrictions and the space in your airport transfer.</p>${ext('https://bikeboxalan.com/about-bike-box-alan/technical-information-new/','Technical & fit guide')}</div></div></section>`;}
export function hirePage(){return `${pageIntro('Hire details','Collection. Payment. Return.')}<section class="section section-top-small"><div class="shell hire-layout"><div class="hire-timeline"><article><span>01</span><div><h2>Request your dates</h2><p>Send your dates and bike details to hello@bikeboxbath.co.uk. Hire is £11 per calendar day, minimum 5 days, plus a £150 refundable deposit. Your quote is calculated automatically. Availability and collection are confirmed before booking.</p><a class="text-link" href="#/enquire">Choose your dates ${arrow}</a></div></article><article><span>02</span><div><h2>Collect in Bath</h2><p>Bring photo ID. The case and supplied parts are inspected together, with existing marks or damage recorded at handover.</p><p>Payment is verified before collection. Cash is counted and checked for authenticity.</p></div></article><article><span>03</span><div><h2>Return & inspection</h2><p>Return the case and all parts at the agreed time. Its condition is checked against the collection record before the deposit is settled under the agreed hire terms.</p></div></article></div><aside class="payment-panel"><p class="eyebrow">Hire charges</p><h2>£11 / day.</h2><dl><div><dt>Minimum hire</dt><dd>5 calendar days · £55</dd></div><div><dt>Refundable deposit</dt><dd>£150</dd></div><div><dt>Late return</dt><dd>£40 per day late</dd></div></dl><h3>Payment methods</h3><dl><div><dt>PayPal</dt><dd>Payment details or an invoice are provided with your hire.</dd></div><div><dt>BACS</dt><dd>Funds must be received before the case is released.</dd></div><div><dt>Cash on collection</dt><dd>Notes are counted and checked at handover.</dd></div></dl><a class="quiet-link" href="#/terms">Hire terms ${arrow}</a></aside></div></section>`;}
export function aboutPage(){return `${pageIntro('Contact','hello@bikeboxbath.co.uk')}<section class="section section-top-small"><div class="shell contact-layout"><div class="contact-photo"><img src="assets/bath.jpg" alt="Pulteney Bridge, Bath" width="1600" height="1000"></div><div><h2>Bike box hire in Bath.</h2><p>For dates, bike fit and collection enquiries.</p><a class="button" href="mailto:hello@bikeboxbath.co.uk">Email Bike Box Bath ${arrow}</a><a class="text-link" href="#/enquire">Add dates & bike details first ${arrow}</a><dl class="spec-list"><div><dt>Collection / return</dt><dd>Bath, by appointment</dd></div><div><dt>Payment</dt><dd>PayPal, BACS or cash</dd></div></dl></div></div></section>`;}
export function airlinesPage(){return `${pageIntro('Airline guide','Flying with your bike.','Weight allowances, extra charges and packing rules.')}<section class="section section-top-small"><div class="shell"><div class="weight-primer"><strong>13.5 <span>kg</span></strong><p>Empty case weight. A 23 kg allowance leaves around 9.5 kg for your bike and permitted packing.</p><a class="quiet-link" href="#/airlines?weight">Weight calculator ↓</a></div><div class="airline-title"><h2>Allowances & charges.</h2><p class="small">Checked ${AIRLINE_CHECKED}. Per-flight charges are separate from box hire.</p></div><div class="airline-table"><div class="airline-table-head" aria-hidden="true"><span>Airline</span><span>Packed weight</span><span>Additional charge</span></div>${AIRLINES.map(a=>`<article class="airline-row"><h3>${a.name}</h3><p class="airline-weight">${a.weight}</p><div><p class="airline-cost">${a.cost}</p><details><summary>Rules & source links <span aria-hidden="true">+</span></summary><p>${a.note}</p><div class="source-links">${a.links.filter((l,i,arr)=>arr.findIndex(x=>x[1]===l[1])===i).map(([label,url])=>ext(url,label)).join('')}</div></details></div></article>`).join('')}</div><p class="guide-warning">Check the operating airline’s rules for both flights. Case dimensions are approximately 133 × 94 × 50 cm. Airline handlebar, pedal, battery and packing requirements still apply.</p></div></section><section class="section calculator-section" id="weight-tool"><div class="shell calculator-layout"><div><p class="eyebrow">Packed weight</p><h2>Case + bike + packing.</h2><p>Enter your bicycle allowance and the actual weights.</p></div><form id="weight-form" class="calculator"><div class="field-grid"><label>Empty case (kg)<input name="caseWeight" type="number" value="13.5" min="0" max="60" step="0.1" required></label><label>Your bike (kg)<input name="bikeWeight" type="number" min="0" max="60" step="0.1" placeholder="8.5" required></label><label>Permitted packing (kg)<input name="packingWeight" type="number" value="0" min="0" max="60" step="0.1" required></label><label>Your allowance (kg)<input name="limit" type="number" min="0.1" max="100" step="0.1" placeholder="23" required></label></div><button class="button" type="submit">Calculate <span aria-hidden="true">→</span></button><output id="weight-result" aria-live="polite"></output></form></div></section>`;}
export function termsPage(){return `${pageIntro('Hire terms','Before hiring.')}<section class="section section-top-small"><article class="shell reading-copy"><h2>Booking & price</h2><p>A request is an enquiry, not a confirmed booking. Hire is £11 per calendar day, with a minimum of 5 days (£55). Collection and return dates both count as hire days. A £150 refundable deposit is added to the hire charge. Availability, cancellation arrangements and collection and return times are agreed before a booking is confirmed. Late returns are charged at £40 for each calendar day after the agreed return date.</p><h2>Collection checks</h2><p>Photo ID is checked in person. Payment must be verified; cash is counted and checked for authenticity. The case and its supplied parts are inspected and existing wear or damage is documented with photographs or a written checklist.</p><h2>During hire</h2><p>Follow the manufacturer’s packing instructions and your airline’s requirements. Check fit, packed weight, case dimensions and your own bike and travel insurance. Report damage, missing parts or changes to return plans promptly.</p><h2>Return & deposit</h2><p>The case and parts are inspected against the collection record. Any damage or missing parts are documented and discussed. Deposit settlement and any charges follow the hire terms agreed before collection.</p><h2>Payment</h2><p>PayPal, BACS or cash on collection, by agreement. This website does not take payments.</p><a class="text-link" href="mailto:hello@bikeboxbath.co.uk">hello@bikeboxbath.co.uk ${arrow}</a></article></section>`;}
export function privacyPage(){return `${pageIntro('Privacy','Your information.')}<section class="section section-top-small"><article class="shell reading-copy"><h2>Enquiry details</h2><p>Details stay in page memory until you choose to send. When the rental service is connected, Send hire request stores your name, email, bike details, dates, message and calculated quote in Bike Box Bath’s rental database for managing the hire. Your acceptance of the hire terms and its date are stored with a submitted request. Payment, inspection and deposit status may be recorded by authorised staff. No card information or ID scans are collected here.</p><p>The email button opens a draft in your email app. You review and send it there. Copying or downloading saves the text to your clipboard or device. Sent emails are handled by your email provider and Bike Box Bath. Contact hello@bikeboxbath.co.uk about access, corrections, deletion or record retention.</p><h2>ID & payment information</h2><p>ID is checked in person. Do not email ID document copies, ID numbers, card details or banking credentials. Ask Bike Box Bath about retention of enquiry, hire and condition records before booking.</p><h2>Website services</h2><p>The admin area uses an essential sign-in cookie. No advertising or analytics cookies are added by this site. Fonts and images are hosted with this website. Hosting, email and sign-in providers may keep essential logs or cookies. External airline and product links have their own privacy notices.</p><a class="text-link" href="mailto:hello@bikeboxbath.co.uk">Privacy enquiries ${arrow}</a></article></section>`;}
export function creditsPage(){return `${pageIntro('Credits','Images & product sources.')}<section class="section section-top-small"><article class="shell reading-copy"><h2>Bike Box Alan</h2><p>Triathlon Aero Easyfit product photographs and specifications: ${ext('https://bikeboxalan.com/product/triathlon-easyfit/','Bike Box Alan')}. Photographs show the model; decals and condition of the rental unit may differ.</p><p>${ext('https://bikeboxalan.com/about-bike-box-alan/technical-information-new/','Technical & fit information')}</p><h2>Bath</h2><p>Pulteney Bridge, Bath, front view. Fahdshariff, 2007. Public domain. ${ext('https://commons.wikimedia.org/wiki/File:Pulteney_Bridge,_Bath,_front_view.jpg','Original photograph')}</p><h2>Fonts</h2><p>Barlow and Barlow Condensed. SIL Open Font License; licence files are included with the site.</p><h2>Airline policies</h2><p>Official policy links accompany each entry in the <a href="#/airlines">airline guide</a>.</p></article></section>`;}
